// pageRerenderItemKey builds the idx_swi_dedup key for a per-page rerender
// work item. It MUST carry the render-MODE discriminator, or a reason-less
// assemble-only request and a reason-bearing section-render request for the
// same page collide and one is silently dropped (bugs_open/024 defect 6).
func pageRerenderItemKey(pageName string, siteID uuid.UUID, keyReason string) string {
	if keyReason == "" {
		keyReason = "assemble"
	}
	return fmt.Sprintf("page_rerender_%s_%s_%s", pageName, siteID, keyReason)
}
